          heading: "¿Cuánto concreto extra hay que pedir por desperdicio?",
          paragraphs: [
            "El 10 por ciento predeterminado sirve para la mayoría de la losa residencial. Use cerca de 5 por ciento en un rectángulo pequeño y bien cimbrado sobre subrasante nivelada y compactada donde pueda medir dos veces. Use 12 a 15 por ciento con curvas, varios niveles, terrenos inclinados o suelo sobreexcavado. La pérdida es real, no teórica: hundimientos de la subrasante, cimbras que se abren con el peso del concreto fresco, derrames de la canaleta y la carretilla, material adherido al tambor y cilindros de prueba se llevan volumen de la carga. Sobreexcavar apenas media pulgada en 400 ft² son 16,7 ft³ por sí solos, o 0,62 yd³.",
            "Quedarse corto cuesta mucho más que quedarse largo. Un vaciado que se detiene mientras alguien va por más material deja una junta fría que es defecto estructural y estético, y una segunda entrega pequeña suele traer su propio cargo mínimo. Agregue el margen y luego redondee al incremento que el proveedor realmente vende. Mantenga el margen separado del espesor en sus notas para que nadie confunda después un colchón de 10 por ciento con una losa más gruesa. Por último, recuerde que el margen cubre solo incertidumbre de estimación. No compensa un espesor sin verificar, una base faltante ni un refuerzo que nunca se diseñó.",
          ],
