            "Convierta primero el vaciado a pies cúbicos y luego divida entre el rendimiento impreso en el saco. El volumen en pies cúbicos es largo × ancho × espesor, todo en pies, así que un espesor de 4 in entra en la fórmula como 0,333 ft. Quikrete Concrete Mix rinde aproximadamente 0,30 ft³ en saco de 40 lb, 0,375 ft³ en 50 lb, 0,45 ft³ en 60 lb, 0,60 ft³ en 80 lb y 0,675 ft³ en saco de 90 lb [1]. Sakrete High Strength Concrete Mix indica las mismas cifras de 0,30, 0,45 y 0,60 ft³, con 0,66 ft³ para su saco de 90 lb [2]. Como los sacos se venden enteros, la calculadora siempre redondea el conteo final hacia arriba.",
            "Un ejemplo concreto aclara la secuencia. Una plataforma para equipo de 4 ft × 6 ft con 4 in de espesor son 24 ft² × 0,333 ft = 8,0 ft³. Con el margen de 10 por ciento queda en 8,8 ft³. Al dividir entre 0,60 ft³ resultan 14,7, así que compre 15 sacos de 80 lb, es decir 1.200 lb de material. La misma plataforma en sacos de 60 lb da 8,8 entre 0,45, o 19,6, así que 20 sacos. Elija un solo peso de saco por pedido y manténgalo, porque mezclar tamaños en un mismo cálculo produce un conteo que no coincide con nada de la tarima.",
