            "No confunda el peso del saco con el volumen ni con la resistencia. Las 80 lb son el peso de material seco; el número útil para estimar es el rendimiento en pies cúbicos. Quikrete indica un peso unitario cercano a 140 lb por ft³ para el concreto endurecido, razón por la cual 0,60 ft³ de concreto terminado salen de un saco de 80 lb más unas 6 pintas de agua [1]. Tanto Quikrete Concrete Mix como Sakrete High Strength Concrete Mix declaran 4.000 psi a 28 días según ASTM C39, y ambos cumplen ASTM C387 para materiales secos combinados empacados [1][2].",
