            "Los hoyos redondos usan la fórmula del cilindro, y la calculadora acepta dimensiones cuadradas equivalentes o un volumen directo. Un tubo de cartón de 10 in de diámetro y 42 in de profundidad da pi × (5 entre 12)² × 3,5 ft = 1,91 ft³, o 2,1 ft³ con desperdicio, es decir 4 sacos de 80 lb. Un tubo de 12 in a la misma profundidad son 2,75 ft³, o 3,02 ft³ con margen, y necesita 6 sacos. Reste el volumen del poste solo si es grande respecto al hoyo; para un poste de madera de 4 × 4 in en un hoyo de 12 in la diferencia cabe dentro del margen.",
