            "En la práctica eso significa que el sistema de climatización debe operar en condiciones normales de habitación antes de la entrega, que la losa o el contrapiso se prueben en vez de estimarse a ojo, y que las holguras de expansión en muros y columnas queden abiertas y cubiertas con moldura, no rellenadas. El laminado tipo click y el LVP de núcleo rígido se mueven menos que la madera sólida, pero igual requieren holgura perimetral y, en corridas largas, perfiles de transición. Nada de esto cambia los pies cuadrados ni el número de cajas: cambia si el piso queda plano, cerrado y silencioso tras la primera temporada de calefacción.",
