            "Compre cajas completas y guarde el sobrante. El azulejo se cuece por lotes y la variación de tono entre corridas de producción es normal, así que una pieza de reposición comprada dos años después puede no coincidir. Una caja de repuesto guardada plana y seca es un seguro barato ante una pieza rota sobre una viga o una reparación de plomería. Verifique la cobertura y el número de piezas impresos en la caja en vez de suponerlos: el mismo tamaño nominal puede venir en 8, 10 o 12 piezas según el espesor. Trate el resultado como estimación de planeación de azulejo de campo, no como sustituto de un plano de trazo ni del levantamiento del instalador.",
