            "Primero sume el área de superficie y luego divida entre el área de una placa. Un panel de 4 ft × 8 ft son 32 ft² y uno de 4 ft × 12 ft son 48 ft², así que el conteo es el área con desperdicio dividida entre 32 o 48, redondeada a placas enteras. En una habitación, el área de muros es perímetro × altura y el área de cielo es largo × ancho. Un cuarto de 12 ft × 12 ft con muros de 8 ft da un perímetro de 48 ft, así que los muros son 384 ft², el cielo agrega 144 ft² y el total combinado es 528 ft². La misma aritmética sirve para tablaroca, panel de yeso, placa de yeso y cartón-yeso, porque la calculadora solo atiende las dimensiones del panel.",
