            "Para la pendiente, apoye un nivel en horizontal contra la tabla de borde, mida 12 pulgadas sobre él y luego mida en vertical hasta la superficie del techo; esa distancia en pulgadas es la subida. Hágalo desde una escalera o una ventana alta en vez de caminar el techo. Los techos complejos con varios planos y pendientes se manejan mejor por sección o con un reporte de medición aérea. Esta calculadora aproxima un techo simple a dos o cuatro aguas con un rectángulo y una pendiente, así que trate el resultado como estimación de presupuesto y pedido, no como evaluación estructural.",
