            "El desperdicio se agrega al área inclinada antes de dividir entre 100, que es como lo maneja esta calculadora. Note lo que el desperdicio no cubre: la hilada de arranque, un producto aparte a lo largo de aleros y bordes, y el remate de cumbrera y cumbreras, que se vende por pie lineal. La guía de mitigación de FEMA para techos inclinados recomienda clavos de vástago anillado, colocación del sujetador dentro de la zona de clavado del fabricante y membrana mejorada bajo la teja en regiones de viento alto [1]. La guía FEMA P-499 dedica una hoja técnica a la teja asfáltica en regiones de viento alto [2].",
