            "**Tres paquetes cubren un cuadrado de techo en la mayoría de las tejas asfálticas, unos 33,3 ft² por paquete.** Los perfiles de diseñador y resistentes al impacto suelen venir en cuatro o cinco paquetes por cuadrado, bajando la cobertura a 25 o 20 ft². La envoltura tiene la única cifra confiable.",
