            "La tierra cribada es vegetal pasada por malla para quitar piedras y desechos, lo que facilita mucho rastrillarla a una profundidad uniforme. Las tierras de jardín y las mezclas para camas elevadas son productos fabricados con suelo, composta y a veces corteza o turba, así que son más ligeras, más ricas y se asientan más que la tierra nativa: el NRCS reporta una densidad aparente promedio de 0,22 g/cm³ para la materia orgánica frente a 1,45 para el suelo franco [1]. El NRCS también señala que los suelos urbanos y sus propiedades son más variables que en paisajes no desarrollados, y publica estudios urbanos hasta unos 2 metros de profundidad, gratis por Web Soil Survey [2].",
