            "La profundidad por sí sola no corrige la compactación de abajo. El NRCS reporta que una densidad aparente por encima de aproximadamente 1,80 g/cm³ en suelos arenosos, 1,65 g/cm³ en limosos y 1,47 g/cm³ en arcillosos restringe el crecimiento de raíces, mientras que las densidades ideales para el crecimiento vegetal están por debajo de 1,60, 1,40 y 1,10 respectivamente [3]. Extender tierra rica sobre una plataforma de obra compactada crea una zona radicular somera que se seca y se encharca por turnos. Afloje primero la subrasante, mezcle la interfaz en vez de dejar un límite abrupto y espere un asentamiento de 10 a 20 por ciento tras el primer riego a fondo.",
