            "Parta del área neta de muro y divida entre la cobertura de un rollo. El área bruta es perímetro × altura del cielo; reste el área total de puertas y ventanas para obtener la cifra neta. Los rollos son el área neta con desperdicio dividida entre la cobertura por rollo, redondeada a rollos enteros, y la repetición del diseño aumenta el desperdicio por tira. El dato que arruina las estimaciones es la cobertura por rollo, porque varía enormemente. Según la Wallcovering Installers Association, un rollo sencillo americano contiene de 34 a 36 ft² sin importar si mide 18 in o 36 in de ancho, mientras que un rollo métrico o europeo contiene solo 28 a 30 ft² por rollo sencillo [1].",
