            "Las reglas generales se agrupan entre 15 y 25 BTU por hora por pie cuadrado, y esta calculadora usa 20 BTU/ft² como valor predeterminado para un clima mixto moderado. Pero la razón no es constante con el tamaño del espacio. La tabla de capacidad de enfriamiento de ENERGY STAR asocia 100 a 150 ft² con 5.000 BTU/h —unos 33 BTU/ft² en el extremo superior de esa banda— luego 450 a 550 ft² con 12.000 BTU/h (unos 22), 700 a 1.000 ft² con 18.000 BTU/h (18) y 2.000 a 2.500 ft² con 34.000 BTU/h (unos 14) [1]. Los espacios pequeños tienen proporcionalmente más envolvente e infiltración por pie cuadrado.",
            "El clima, el aislamiento, el área de vidrio, las filtraciones de aire, la orientación, la ocupación y las ganancias internas mueven la cifra, y por eso esta herramienta expone los multiplicadores de clima, aislamiento y sol en lugar de esconderlos en una constante. Las zonas cálidas y húmedas se ubican en el extremo alto del rango; las envolventes herméticas y bien aisladas en climas templados, en el bajo. Sea honesto con el aislamiento: el error más común es declarar una buena envolvente en una casa con muros de los años ochenta y luego sobredimensionar el equipo para compensar. Tome el resultado como estimación de planificación para una sola zona.",
