            "Después aplique los ajustes que publica ENERGY STAR: reduzca la capacidad 10 por ciento si la habitación está muy sombreada, aumente 10 por ciento si es muy asoleada, sume 600 BTU por cada ocupante adicional después de dos y sume 4.000 BTU si la unidad se usa en una cocina [1]. Una cocina muy asoleada de 500 ft² ocupada habitualmente por cuatro personas pasa de 12.000 a 12.000 × 1,10 + 4.000 + 1.200 = 18.400 BTU/h: la mitad más que la cifra inicial. ENERGY STAR es directo al advertir que más grande no siempre es mejor: un equipo sobredimensionado cuesta más, desperdicia energía y no enfría mejor [1].",
