            "El tonelaje nominal es una etiqueta, no una garantía. La capacidad real varía con la temperatura exterior, la temperatura de bulbo húmedo interior, el caudal de aire sobre el serpentín y la carga de refrigerante, y en climas húmedos el reparto entre calor sensible y latente importa tanto como el total. De eso trata el Manual S de ACCA: explica cómo elegir el equipo de calefacción y refrigeración para una vivienda según el clima local y las especificaciones de construcción, cubriendo once tipos de equipos y el uso de los datos de desempeño del fabricante [2]. Dimensionar solo por toneladas nominales es como un sistema correcto termina fallando en control de humedad.",
