            "Empiece por la huella: 20 ft × 15 ft = 300 ft². Con el valor predeterminado de 20 BTU/ft², la carga base es 300 × 20 = 6.000 BTU/h, es decir 0,5 toneladas. Ahora aplique los multiplicadores. Una habitación expuesta al sol con aislamiento mediocre en clima cálido podría llevar un factor solar de 1,10 y un factor de aislamiento de 1,15: 6.000 × 1,10 × 1,15 = 7.590 BTU/h, o 0,63 toneladas, el resultado nombrado. La tabla de ENERGY STAR ubica de forma independiente 300 a 350 ft² en 8.000 BTU/h [1], así que ambas rutas apuntan a la misma clase de equipo de 7.500 a 8.000 BTU/h.",
            "Luego verifique contra volumen y ocupación. Si esa misma habitación de 300 ft² tiene cielo de 10 pies, contiene 3.000 ft³ en lugar de 2.400 ft³, y ENERGY STAR aclara que sus capacidades se calculan con cielo de 8 pies [1]. Cuatro ocupantes habituales suman 1.200 BTU según la regla de ENERGY STAR, llevando 8.000 a 9.200 BTU/h; si la habitación es cocina, sume otros 4.000 [1]. Nada de esto modela pérdidas en ductos, infiltración medida, valores U de ventanas ni geometría de sombreado. Un cálculo de carga real sí lo hace, y es el paso siguiente para cualquier espacio mayor que una habitación.",
