            "El subdimensionamiento tiene su propia falla: el sistema funciona continuamente y nunca alcanza la temperatura deseada en días de diseño. La salida del dilema es un cálculo de carga, no un número más grande. El Manual J de ACCA es la norma nacional aprobada por ANSI para el cálculo de carga residencial en casas unifamiliares aisladas, estructuras multifamiliares pequeñas, condominios, casas adosadas y viviendas prefabricadas, y ACCA señala que el cálculo de carga correcto, tal como lo define el manual, es exigido por los códigos nacionales de construcción y por la mayoría de estados y municipios [2]. Use esta calculadora para presupuestar; use Manual J y Manual S para seleccionar equipo.",
