            "El largo por sí solo no indica el volumen, porque la altura y el ancho interiores difieren entre flotas y porque los compartimentos sobre la cabina agregan espacio útil solo apto para artículos livianos y blandos. El glosario de mudanzas de la FMCSA llama camión rígido (straight truck) al vehículo de cabina y caja en una sola pieza y lo describe como generalmente la mitad del tamaño y la capacidad de un tractocamión [2], contexto útil cuando una empresa profesional cotiza un transbordo o un vehículo más pequeño para una calle angosta. Antes de reservar, confirme también rampa o plataforma elevadora, altura de la puerta y separación de rieles de amarre.",
