            "La huella en el sitio importa tanto como la capacidad. Una caja de 22 pies necesita una aproximación recta bastante más larga que el propio contenedor para que el camión lo deslice y lo vuelva a cargar, además de espacio libre en altura para el brazo. Pida al transportista la huella exacta de entrega, porque los camiones y sistemas de cable difieren. Mida el ancho de la entrada, observe ramas bajas y líneas aéreas, y verifique si su municipio exige permiso para colocarlo en la vía pública. Un contenedor que no puede colocar legalmente es peor que uno un poco pequeño. Coloque triplay bajo los rieles para proteger el pavimento y oriente la puerta hacia donde cargará las piezas más pesadas.",
