            "La separación también puede favorecerle. La EPA reporta que en 2018 se generaron 600 millones de toneladas de escombro de construcción y demolición en Estados Unidos, más del doble de los residuos sólidos municipales, y que alrededor de 143,8 millones de toneladas fueron a relleno sanitario mientras el resto se destinó a agregado, productos manufacturados, combustible, composta y mantillo o mejorador de suelo [1]. El concreto limpio, la madera limpia, el metal y el cartón suelen tener salidas propias, a veces con tarifa de disposición menor que el escombro mixto. Si su proyecto genera un flujo grande de un solo material, pregunte si conviene un contenedor dedicado. Esta calculadora dimensiona un contenedor, así que córrala una vez por flujo si separa.",
