            "No, y duplicarlo es fácil sin darse cuenta. Muchas calculadoras de área y conteo ya aplican una tolerancia internamente, así que pasar su resultado a una segunda calculadora de desperdicio compone los factores. Componer es multiplicativo, no aditivo: 100 unidades a 10% y luego 5% dan 100 × 1,10 × 1,05 = 115,5, no 115. Con 10% y luego 10% llega a 121 en vez de 120. El error parece trivial en una partida y deja de parecerlo en un pedido de 4.000 ft², donde el excedente además hay que retirarlo: los factores de la EPA sitúan la madera dimensionada limpia en 169 lb por yarda cúbica y el panel de yeso en 467 lb por yarda cúbica [2].",
            "Si realmente tiene dos etapas independientes de pérdida, combínelas de forma deliberada. El factor aditivo combinado exacto para etapas a y b es (1 + a)(1 + b) − 1, así que 10% de pérdida por corte más 5% de descarte es 1,10 × 1,05 − 1 = 15,5%, que captura como un único 15,5%. Esa es una composición honesta, capturada una sola vez. Lo que no debe hacer es dejar que una etapa quede escondida en una herramienta previa y agregar otra aquí por costumbre. Imprima la cuantificación neta, el factor y la cantidad pedida uno al lado del otro, y pida a otra persona que confirme que la columna neta no lleva ninguna tolerancia.",
