            "Multiplique los pies cúbicos por 0,0283168 para obtener metros cúbicos, o divida entre 35,3147. El factor no es arbitrario: una pulgada equivale exactamente a 2,54 cm, así que un pie equivale exactamente a 0,3048 m y un pie cúbico es 0,3048³ = 0,028316846592 m³ exactos. En el otro sentido, 1 m³ = 35,3147 ft³. Un dormitorio de 960 ft³ son 27,2 m³; una sala de 2.700 ft³ son 76,5 m³. Para yardas cúbicas divida los pies cúbicos entre 27, y para galones estadounidenses multiplique por 7,48052: ese dormitorio de 960 ft³ contiene unos 7.181 galones de aire.",
