            "Los cambios de aire por hora (ACH) equivalen al caudal en pies cúbicos por minuto × 60 ÷ volumen de la habitación en pies cúbicos. Un suministro de 300 cfm en una habitación de 2.400 ft³ entrega 300 × 60 ÷ 2.400 = 7,5 ACH. Invierta el cálculo para dimensionar equipo: para llegar a 5 ACH en una habitación de 2.700 ft³ necesita 2.700 × 5 ÷ 60 = 225 cfm de aire limpio entregado. Por eso el volumen, y no el área de piso, es el denominador honesto en preguntas de ventilación y filtración, y por eso un cielo abovedado con la misma huella exige más caudal para el mismo número de cambios.",
            "La tabla de dimensionamiento de purificadores portátiles de la EPA se basa en la misma relación. Asocia 100 ft² con un CADR mínimo de 65 cfm, 300 ft² con 195 cfm y 600 ft² con 390 cfm, y aclara que los valores de CADR están calculados para un cielo de 8 pies [1]. Convierta cada par a volumen y todas las filas caen cerca de 4,9 cambios de aire por hora: 65 × 60 ÷ 800 = 4,88. La EPA agrega que con cielos de más de 8 pies conviene considerar una unidad dimensionada para un área mayor [1]. Con el volumen real puede verificar en una línea cualquier afirmación de cobertura del fabricante.",
