            "Si desea un objetivo más alto, resuelva directamente: 2.700 ft³ × 8 ACH ÷ 60 = 360 cfm. Dos unidades más pequeñas pueden repartir la carga, y la EPA señala que cuando ningún producto disponible cubre el área se puede considerar usar varios purificadores [1]. En un plano abierto mida todo el espacio conectado y no la habitación nominal: una sala de 2.700 ft³ abierta a un comedor de 1.800 ft³ es un problema de 4.500 ft³. Recuerde que el CADR se mide normalmente a la velocidad más alta del equipo, así que un ajuste silencioso entrega menos cambios de aire que los que sugiere la etiqueta [1].",
