            "Los anclajes reales ayudan. La Encuesta de Costos de Construcción 2024 de la NAHB reporta que la utilidad del constructor promedió 11,0% del precio de venta de una vivienda unifamiliar nueva, con gastos generales y de administración en 5,7%, comisión de ventas en 2,8%, costo financiero en 1,5% y mercadotecnia en 0,8% [2]. Una utilidad de 11,0% del precio es una cifra de margen; el markup equivalente sobre el 89,0% restante de costo es 0,11 ÷ 0,89 = 12,4%. La NAHB también señala que la participación promedio de largo plazo de la utilidad antes de impuestos desde 1998 es 9,8% [2]. Son promedios nacionales de constructores de vivienda nueva, no una meta para una empresa de remodelación, pero muestran lo estrecha que parece la brecha markup-margen en porcentajes bajos.",
