            "No existe un número nacional correcto, y cualquier página que le entregue uno está adivinando. El markup que necesita lo fijan sus propios gastos generales y su propia meta de utilidad, no un rumor del sector. Hágalo al revés: si el gasto general anual es O y espera vender C pesos de costo directo en el año, el markup que apenas cubre gastos generales es O ÷ C. Cualquier meta de utilidad se coloca encima. Como ilustración aritmética, un taller con $120.000 de gastos generales que espera $600.000 de costo directo necesita 20% de markup solo para no perder; agregar una meta de 10% de utilidad sobre costo lleva el markup requerido a 30%, que cotiza $1.000 de costo en $1.300.",
            "Luego importan dos decisiones estructurales. Primero, defina si aplica el mismo recargo a mano de obra y materiales o recargos separados. Muchos contratistas aplican un factor menor a compras grandes de material y uno mayor a la mano de obra, porque esta carga el riesgo de supervisión, retrabajo y garantía. Segundo, defina si cotiza precio fijo único o costo más honorario desglosado. Ambos esquemas se sostienen; cambiar de uno a otro a mitad del proyecto no. Tome todo esto como aritmética de planeación y no como asesoría financiera, fiscal o legal: la SBA recomienda trabajar con un contador público o tenedor de libros para que gastos generales, nómina y costo de lo vendido queden bien registrados [3].",
